mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.25) * p.xz;
  float d = length(p + vec3(0.0, 1.2, 0.0)) - 0.55;
  vec3 q = p;
  for (int i = 0; i < 4; i++) {
    q = abs(q) - vec3(0.42, 0.32, 0.42);
    q.xy = rot(0.65) * q.xy;
    q.yz = rot(0.45) * q.yz;
    d = min(d, length(q) - 0.14);
  }
  return d;
}
